  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `recommended_crops` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `fertilizer_plan` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `ai_model` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
